use super::*;
fn from_fn(atoms:Vec<u64>,f:impl Fn(usize)->bool)->Truth{let mut t=Table::low(0);for row in 0..1usize<<atoms.len(){t.set(row,f(row)as u64);}Truth::canonical(atoms,t)}
fn eval(t:&Truth,assignment:usize)->u64{let row=t.atoms.iter().enumerate().map(|(i,&a)|((assignment>>a)&1)<<i).sum();t.table.bit(row)}
#[test]fn high_rows_and_removed_variables_keep_exact_cofactors(){let f=|r:usize|(r&1!=0&&r>>8&1!=0)^(r>>2&1!=0||r>>5&1==0);let t=from_fn((0..9).collect(),f);assert_eq!(t.atoms,vec![0,2,5,8]);for r in 0..512{assert_eq!(eval(&t,r),f(r)as u64);}}
#[test]fn complement_masks_all512_rows_and_no_unused_bits(){let t=from_fn((0..9).collect(),|r|r.count_ones()%2==1);let n=t.complement();assert_eq!(n.complement(),t);assert!(t.complements(&n));for r in 0..512{assert_eq!(eval(&n,r),1-eval(&t,r));}for count in 0..10{let m=Table::mask(count);for r in 0..512{assert_eq!(m.bit(r),(r<(1usize<<count))as u64);}}}
#[test]fn nine_variable_and_xor_match_independent_scalar_values(){let a=from_fn(vec![0,2,4,6,8],|r|(r.wrapping_mul(37)^r>>2)&8!=0);let b=from_fn(vec![1,3,5,7],|r|(r.wrapping_mul(19)^r>>1)&4!=0);let mut s=Support{qubits:vec![],bits:vec![],base_condition:Truth::constant(true),condition_stack:vec![],next_atom:100};let x=s.xor(&a,&b);let y=s.and(&a,&b);for r in 0..512{assert_eq!(eval(&x,r),eval(&a,r)^eval(&b,r));assert_eq!(eval(&y,r),eval(&a,r)&eval(&b,r));}}
#[test]fn unsupported_whole_expression_gets_fresh_distinct_atoms(){let a=from_fn((0..9).collect(),|r|r.count_ones()%2==1);let b=from_fn(vec![9],|r|r==1);let mut s=Support{qubits:vec![],bits:vec![],base_condition:Truth::constant(true),condition_stack:vec![],next_atom:100};let x=s.combine(&a,&b,true);let y=s.combine(&a,&b,true);assert_eq!(x.atoms,vec![100]);assert_eq!(y.atoms,vec![101]);assert_ne!(x,y);assert!(!x.is_zero()&&!x.is_one());}
